// CONSTRUIRE PAGE — liste de toutes les fiches du tableau Prospection
// ===== CONFIG : noms des colonnes du tableau (à ajuster si besoin) =====
const CLE_ACCES = 'NfUdXKpkIT86U1NLVffoj0cG';
const COL = {
  cle: 'cle_unique',
  auteur: 'auteur',
  livre: 'livre',
  chaine: 'chaine',
  statut: 'statut',
  email: 'email_contact',
  source: 'source_contact_validee',
  candidats: 'emails_candidats',
  lien: 'source_livre',
  date_envoi: 'date_envoi',
  ouvert: 'ouvert_le',
  objet: 'objet_auteur',
  message: 'message_auteur',
};
// =====================================================================

const q = $('PAGE - ouverture').first().json.query || {};
if (q.k !== CLE_ACCES) {
  return [{ json: { html: '<!doctype html><meta charset="utf-8"><p>Accès refusé.</p>' } }];
}

const enTexte = h => h
  .replace(/<img[^>]*>/gi, '')
  .replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|h\d)>/gi, '\n\n').replace(/<\/(div|li)>/gi, '\n').replace(/<li[^>]*>/gi, '- ')
  .replace(/<[^>]+>/g, '')
  .replace(/&nbsp;/g, ' ').replace(/&#39;|&apos;/g, "'").replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&')
  .replace(/\n{3,}/g, '\n\n').trim();
// Adresses trouvées par la recherche automatique, les plus probables d'abord
const candidats = txt => {
  try {
    const vus = new Set();
    return JSON.parse(txt || '[]')
      .filter(c => c && c.email)
      .sort((a, b) => (a.priorite || 9) - (b.priorite || 9))
      .filter(c => { const e = c.email.toLowerCase(); if (vus.has(e)) return false; vus.add(e); return true; })
      .slice(0, 5)
      .map(c => ({ email: c.email, type: c.categorie_contact || '' }));
  } catch (e) { return []; }
};
const val = (r, k) => (r[COL[k]] == null ? '' : String(r[COL[k]]).trim());
const fiches = $input.all()
  .map(i => i.json)
  .filter(r => (val(r, 'cle') || val(r, 'auteur')) && val(r, 'statut') !== 'CONFIG')
  .map(r => ({
    cle: val(r, 'cle'),
    auteur: val(r, 'auteur'),
    livre: val(r, 'livre'),
    chaine: val(r, 'chaine'),
    statut: val(r, 'statut'),
    email: val(r, 'email'),
    source: val(r, 'source'),
    linkedin: '',
    candidats: candidats(val(r, 'candidats')),
    lien: val(r, 'lien'),
    date_envoi: val(r, 'date_envoi'),
    ouvert: val(r, 'ouvert'),
    objet: val(r, 'objet'),
    message: enTexte(val(r, 'message')),
  }))
  .reverse(); // les plus récentes en haut

const data = JSON.stringify(fiches).replace(/</g, '\\u003c');

const html = `<!doctype html>
<html lang="fr"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Prospects Impacteur</title>
<style>
:root{--bg:#f6f6f4;--card:#fff;--txt:#1d1d1b;--mut:#6b6b66;--bd:#e2e2dc;--acc:#2f8f6f;--lien:#2f7f63;--ok:#1d7a3e;--warn:#a35c00;--ko:#b3261e;--champ:#fbfbf9}
@media (prefers-color-scheme:dark){:root{--bg:#1c1c1c;--card:#232322;--txt:#ececea;--mut:#a3a39d;--bd:#3a3a36;--acc:#78c2a4;--lien:#78c2a4;--ok:#6cc58d;--warn:#e0a24a;--ko:#ef8a82;--champ:#1c1c1c}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--txt);font:16px/1.45 system-ui,-apple-system,Segoe UI,Roboto,sans-serif}
.w{max-width:1000px;margin:auto;padding:20px 16px 48px}h1{font-size:26px;margin:0 0 10px}
.intro{color:var(--mut);margin:0 0 14px}
.bar{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 18px}
.bar button{border:1px solid var(--bd);background:var(--card);color:var(--txt);border-radius:999px;padding:6px 12px;cursor:pointer;font-size:14px}
.bar button.on{background:var(--acc);border-color:var(--acc);color:#111}
.bar input{flex:1;min-width:180px;border:1px solid var(--bd);background:var(--card);color:var(--txt);border-radius:8px;padding:7px 10px;font-size:15px}
#liste{display:grid;gap:14px}
.f{background:var(--card);border:1px solid var(--bd);border-radius:12px;padding:16px 18px;display:grid;gap:10px}
.top{display:flex;flex-wrap:wrap;align-items:center;gap:8px 12px}.nom{font-weight:700;text-transform:uppercase}
.meta{color:var(--mut)}.meta a{color:var(--lien)}
.tag{font-size:13px;padding:2px 10px;border-radius:999px;border:1px solid var(--bd)}
.t-sans{color:var(--warn);border-color:var(--warn)}.t-pret{color:var(--lien);border-color:var(--lien)}.t-env{color:var(--ok);border-color:var(--ok)}.t-rej{color:var(--ko);border-color:var(--ko)}
details summary{cursor:pointer}
.ed{display:grid;gap:8px;margin-top:8px}
.ed input,.ed textarea,.ligne input{width:100%;border:1px solid var(--bd);background:var(--champ);color:var(--txt);border-radius:8px;padding:9px 12px;font:inherit}
.ed textarea{min-height:240px;resize:vertical}
.ligne{display:flex;gap:10px}.ligne input{flex:1}
button.p{background:var(--acc);border:0;color:#111;border-radius:8px;padding:9px 18px;font:inherit;cursor:pointer}
.sec{display:flex;flex-wrap:wrap;gap:8px;align-items:center;color:var(--mut)}
.sec button{border:1px solid var(--bd);background:transparent;color:var(--txt);border-radius:8px;padding:7px 12px;font:inherit;font-size:15px;cursor:pointer}
.msg{font-size:14px}.vide{color:var(--mut);padding:20px 0}
</style></head><body><div class="w">
<h1>Tous les prospects (<span id="total"></span>)</h1>
<p class="intro">Tous les auteurs et invités trouvés. Colle l'adresse que tu as trouvée, clique sur « Inviter », et l'invitation part à la prochaine passe d'envoi (10h07 ou 15h07), depuis la boîte de la chaîne. Tu peux retoucher le mail avant.</p>
<div class="bar" id="filtres"></div>
<div id="liste"></div></div>
<script>
const FICHES = ${data};
const CLE = ${JSON.stringify(CLE_ACCES)};
const ENV = /ENVOYE|BROUILLON/i, REJ = /REJET|BLOQUE|DECES/i;
function etat(f){ if(REJ.test(f.statut)) return 'rej'; if(ENV.test(f.statut)) return 'env'; return f.email ? 'pret' : 'sans'; }
const LIB = {sans:'Sans email',pret:'Prête à partir',env:'Envoyée',rej:'Écartée'};
const TYPES = {AUTEUR_DIRECT:'auteur',EDITEUR_CONTACT:'éditeur',EDITEUR_GENERIQUE:'éditeur (général)'};
const FILTRES = [['sans','Sans email'],['pret','Prêtes à partir'],['env','Envoyées'],['rej','Écartées'],['tout','Tout']];
let filtre = 'sans', recherche = '';
const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lienRecherche = f => 'https://www.google.com/search?q=' + encodeURIComponent('"' + f.auteur + '" contact email ' + (f.livre||''));
function barre(){
  const n = k => k==='tout' ? FICHES.length : FICHES.filter(f => etat(f)===k).length;
  document.getElementById('total').textContent = FICHES.length;
  document.getElementById('filtres').innerHTML = FILTRES.map(([k,l]) =>
    '<button data-f="'+k+'" class="'+(k===filtre?'on':'')+'">'+l+' ('+n(k)+')</button>').join('') +
    '<input id="rech" placeholder="Rechercher un nom, un livre…" value="'+esc(recherche)+'">';
}
function carte(f){
  const e = etat(f);
  const liens = [
    f.lien ? '<a href="'+esc(f.lien)+'" target="_blank" rel="noopener">livre / vidéo</a>' : '',
    f.linkedin ? '<a href="'+esc(f.linkedin)+'" target="_blank" rel="noopener">LinkedIn</a>' : '',
    '<a href="'+lienRecherche(f)+'" target="_blank" rel="noopener">chercher l\\'adresse</a>'
  ].filter(Boolean).join(' · ');
  const infos = [f.chaine && ('Chaîne '+esc(f.chaine)), f.email && esc(f.email),
    f.date_envoi && ('envoyée le '+esc(f.date_envoi)), f.ouvert && ('ouverte le '+esc(f.ouvert))].filter(Boolean).join(' · ');
  let h = '<div class="f" data-cle="'+esc(f.cle)+'"><div class="top"><span class="nom">'+esc(f.auteur||'(sans nom)')+'</span>'+
    '<span class="tag t-'+e+'">'+LIB[e]+'</span></div>'+
    '<div class="meta">'+esc(f.livre)+(infos?'<br>'+infos:'')+'</div><div class="meta">'+liens+'</div>';
  if (e==='env') return h+'</div>';
  h += '<details><summary>Voir ou retoucher le mail</summary><div class="ed">'+
    '<input class="objet" value="'+esc(f.objet)+'" placeholder="Objet">'+
    '<textarea class="corps" placeholder="Pas encore d\\'invitation rédigée pour cette fiche">'+esc(f.message)+'</textarea>'+
    '</div></details>'+
    '<div class="ligne"><input type="email" class="adr" placeholder="adresse@retiree.invalid" value="'+esc(f.email)+'">'+
    '<button class="p" data-a="email">Inviter</button></div>'+
    (f.candidats.length && !f.email ? '<div class="sec">Adresses repérées : '+f.candidats.map(c =>
      '<button data-sug="'+esc(c.email)+'">'+esc(c.email)+(TYPES[c.type]?' ('+TYPES[c.type]+')':'')+'</button>').join('')+'</div>' : '')+
    '<div class="sec">Pas d\\'adresse, seulement LinkedIn ou un formulaire ? '+
    '<button data-a="copier">Copier le texte</button><button data-a="manuel">Envoyé de mon côté</button>'+
    (e==='rej' ? '' : '<button data-a="rejeter">Pas celui-là</button>')+
    '<span class="msg"></span></div></div>';
  return h;
}
function rendu(){
  barre();
  const r = recherche.toLowerCase();
  const liste = FICHES.filter(f => (filtre==='tout' || etat(f)===filtre) &&
    (!r || (f.auteur+' '+f.livre+' '+f.email).toLowerCase().includes(r)));
  document.getElementById('liste').innerHTML = liste.length ? liste.map(carte).join('') : '<div class="vide">Aucune fiche ici.</div>';
}
document.addEventListener('click', async ev => {
  const b = ev.target.closest('button'); if(!b) return;
  if (b.dataset.f){ filtre = b.dataset.f; rendu(); return; }
  if (b.dataset.sug){ b.closest('.f').querySelector('.adr').value = b.dataset.sug; return; }
  const c = b.closest('.f'); if(!c || !b.dataset.a) return;
  const f = FICHES.find(x => x.cle === c.dataset.cle);
  const msg = c.querySelector('.msg'), action = b.dataset.a;
  const email = c.querySelector('.adr').value.trim();
  const objet = c.querySelector('.objet').value.trim(), corps = c.querySelector('.corps').value.trim();
  if (action==='copier'){
    try { await navigator.clipboard.writeText(objet+'\\n\\n'+corps); msg.textContent='Texte copié.'; }
    catch(e){ msg.textContent='Copie impossible, sélectionne le texte à la main.'; }
    return;
  }
  if (action==='email' && !/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email)){ msg.textContent='Adresse invalide.'; return; }
  if (action==='email' && !corps){ msg.textContent='Il manque le texte du mail.'; return; }
  if (action==='rejeter' && !confirm('Écarter '+f.auteur+' ?')) return;
  const corpsModifie = corps !== f.message, objetModifie = objet !== f.objet;
  msg.textContent = 'Enregistrement…';
  try {
    const rep = await fetch('impacteur-prospects-action', {method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({k:CLE, cle:f.cle, action, email,
        objet: objetModifie ? objet : undefined, message: corpsModifie ? corps : undefined})});
    const j = await rep.json();
    if (!j.ok) throw new Error(j.erreur || 'erreur');
    if (objetModifie) f.objet = objet; if (corpsModifie) f.message = corps;
    if (action==='email'){ f.email = email.toLowerCase(); f.statut = 'A_VERIFIER'; }
    if (action==='manuel'){ f.statut = 'ENVOYE_MANUEL'; f.date_envoi = j.date || ''; if(email) f.email = email; }
    if (action==='rejeter'){ f.statut = 'REJETE_MANUEL'; }
    rendu();
  } catch(e){ msg.textContent = 'Échec : ' + e.message; }
});
document.addEventListener('input', ev => { if(ev.target.id==='rech'){ recherche = ev.target.value; const p = ev.target.selectionStart; rendu(); const i = document.getElementById('rech'); i.focus(); i.setSelectionRange(p,p); }});
rendu();
</script></body></html>`;

return [{ json: { html } }];

// PREPARER MAJ — transforme un clic de la page en mise à jour d'une ligne du tableau
// ===== CONFIG : mêmes noms de colonnes que dans CONSTRUIRE PAGE =====
const CLE_ACCES = 'NfUdXKpkIT86U1NLVffoj0cG';
const COL = { cle: 'cle_unique', statut: 'statut', email: 'email_contact', type: 'type_contact', source: 'source_contact_validee',
  validation: 'validation_contact', date_envoi: 'date_envoi', maj: 'derniere_mise_a_jour', objet: 'objet_auteur', message: 'message_auteur' };
// ====================================================================

const b = $input.first().json.body || {};
const erreur = m => [{ json: { valide: false, erreur: m } }];
if (b.k !== CLE_ACCES) return erreur('accès refusé');
if (!b.cle) return erreur('fiche inconnue');

const email = String(b.email || '').trim().toLowerCase();
const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const aujourdhui = new Date().toLocaleDateString('fr-CA', { timeZone: 'Europe/Paris' });
const maj = { [COL.cle]: String(b.cle), [COL.maj]: new Date().toISOString() };

// Mail retouché sur la page : écrit tel quel (le tableau stocke du texte simple)
if (typeof b.objet === 'string' && b.objet.trim()) maj[COL.objet] = b.objet.trim();
if (typeof b.message === 'string' && b.message.trim()) maj[COL.message] = b.message.trim();

if (b.action === 'email') {
  if (!emailOk) return erreur('email invalide');
  maj[COL.email] = email;
  maj[COL.type] = 'auteur';
  maj[COL.source] = 'manuel (page prospects)';
  maj[COL.validation] = 'OUI'; // validé par Louis
  maj[COL.statut] = 'A_VERIFIER'; // C l'enverra à sa prochaine passe
} else if (b.action === 'manuel') {
  if (emailOk) maj[COL.email] = email;
  maj[COL.statut] = 'ENVOYE_MANUEL'; // C ne la touche plus
  maj[COL.date_envoi] = aujourdhui;
} else if (b.action === 'rejeter') {
  maj[COL.statut] = 'REJETE_MANUEL';
} else {
  return erreur('action inconnue');
}

return [{ json: { valide: true, date: aujourdhui, maj } }];
